#!/usr/bin/env bash
# Builds the OS graph core (rust/os-graph, feature `wasm`) to WebAssembly and writes the
# generated files the web page embeds:
#
#   web/src/wasm/pkg/graph_kit_os.js     wasm-bindgen glue (--target web, no default module path)
#   web/src/wasm/pkg/graph_kit_os.d.ts   its declarations
#   web/src/wasm/bytes.ts                the .wasm bytes as base64, with the rustc version
#
# The page runs from file:// inside a WKWebView as one classic script, so it cannot fetch a
# .wasm file: the bytes are embedded and initialised with initSync({ module }). The .wasm
# itself is not kept in pkg/.
#
# The glue is generated with --experimental-reset-state-function: web/src/wasm/index.ts calls
# __wbg_reset_state after a panic trap, so the next call re-instantiates a clean instance.
#
# The toolchain is `stable` unless OS_WASM_TOOLCHAIN names another rustup toolchain (CI sets it
# to the version recorded in bytes.ts). Absolute build paths (the checkout, CARGO_HOME) are
# remapped so the bytes do not depend on where the crate is built.
#
# Usage:
#   scripts/build-os-wasm.sh                regenerate the committed files
#   scripts/build-os-wasm.sh --check        build into a temp dir and diff against the committed files
#   scripts/build-os-wasm.sh --check --strict
#                                           as --check, but a toolchain mismatch exits 1
#
# Wasm output is only reproducible with the same rustc, so --check is skipped when the local
# rustc differs from the one recorded in bytes.ts: the skip is printed to stderr and the script
# exits 0, or 1 with --strict. The wasm-bindgen CLI must match the wasm-bindgen version locked
# in rust/Cargo.lock (the glue is only valid for the crate's wasm-bindgen). CI runs --check
# --strict (.github/workflows/ci.yml, job `wasm`) with the recorded rustc, so a stale bundle
# fails the build.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RUST_DIR="$ROOT/rust"
WASM_DIR="$ROOT/web/src/wasm"
PKG_DIR="$WASM_DIR/pkg"
BYTES_TS="$WASM_DIR/bytes.ts"
TARGET_DIR="${CARGO_TARGET_DIR:-$RUST_DIR/target}"
WASM_OUT="$TARGET_DIR/wasm32-unknown-unknown/release/graph_kit_os.wasm"
GENERATED_HEADER="// GENERATED by scripts/build-os-wasm.sh — do not edit"
TOOLCHAIN="${OS_WASM_TOOLCHAIN:-stable}"

mode="build"
strict=0
for arg in "$@"; do
  case "$arg" in
    --check) mode="check" ;;
    --strict) strict=1 ;;
    *) echo "usage: $0 [--check [--strict]]" >&2; exit 2 ;;
  esac
done
if [ "$strict" -eq 1 ] && [ "$mode" != "check" ]; then
  echo "usage: --strict only applies to --check" >&2
  exit 2
fi

local_rustc() {
  rustup run "$TOOLCHAIN" rustc --version
}

# The wasm-bindgen version the crate locks (rust/Cargo.lock) must equal the installed CLI's:
# the glue generated by one version does not match the library built against another.
check_wasm_bindgen_version() {
  local locked installed
  locked="$(sed -n '/^name = "wasm-bindgen"$/{n;s/^version = "\(.*\)"$/\1/p;}' "$RUST_DIR/Cargo.lock" | head -n 1)"
  if [ -z "$locked" ]; then
    echo "error: no wasm-bindgen entry in $RUST_DIR/Cargo.lock" >&2
    exit 1
  fi
  if ! command -v wasm-bindgen >/dev/null 2>&1; then
    echo "error: wasm-bindgen is not on PATH; install wasm-bindgen $locked (the version in rust/Cargo.lock)" >&2
    exit 1
  fi
  installed="$(wasm-bindgen --version | awk '{print $2}')"
  if [ "$installed" != "$locked" ]; then
    echo "error: wasm-bindgen CLI is $installed but rust/Cargo.lock locks wasm-bindgen $locked; install wasm-bindgen $locked and rerun" >&2
    exit 1
  fi
}

# Build the crate and write the three generated files into the directory given as $1.
generate_into() {
  local out="$1"
  # Remap the checkout and CARGO_HOME so the embedded paths are the same on every machine.
  (cd "$RUST_DIR" && RUSTFLAGS="${RUSTFLAGS:-} --remap-path-prefix=$ROOT=/graph-kit --remap-path-prefix=${CARGO_HOME:-$HOME/.cargo}=/cargo" \
    rustup run "$TOOLCHAIN" cargo build --release \
    --target wasm32-unknown-unknown --features wasm -p graph-kit-os)
  wasm-bindgen --target web --omit-default-module-path --experimental-reset-state-function \
    --out-dir "$out" --out-name graph_kit_os "$WASM_OUT"
  local b64
  b64="$(base64 < "$out/graph_kit_os_bg.wasm" | tr -d '\n')"
  {
    printf '%s\n' "$GENERATED_HEADER"
    printf '// rustc: %s\n' "$(local_rustc)"
    printf 'export const OS_GRAPH_WASM_BASE64 = "%s";\n' "$b64"
  } > "$out/bytes.ts"
  rm -f "$out/graph_kit_os_bg.wasm"
}

check_wasm_bindgen_version

if [ "$mode" = "build" ]; then
  tmp="$(mktemp -d "${TMPDIR:-/tmp}/os-wasm.XXXXXX")"
  trap 'rm -rf "$tmp"' EXIT
  generate_into "$tmp"
  mkdir -p "$PKG_DIR"
  cp "$tmp/graph_kit_os.js" "$tmp/graph_kit_os.d.ts" "$PKG_DIR/"
  cp "$tmp/bytes.ts" "$BYTES_TS"
  echo "wrote $PKG_DIR/graph_kit_os.js, graph_kit_os.d.ts and $BYTES_TS"
  exit 0
fi

# --check
if [ ! -f "$BYTES_TS" ]; then
  echo "check failed: $BYTES_TS is missing; run scripts/build-os-wasm.sh" >&2
  exit 1
fi
recorded="$(sed -n 's#^// rustc: ##p' "$BYTES_TS")"
current="$(local_rustc)"
if [ "$recorded" != "$current" ]; then
  echo "SKIPPED (toolchain differs: have $current, generated with $recorded)" >&2
  if [ "$strict" -eq 1 ]; then
    echo "error: --strict: the wasm output is only reproducible with the recorded rustc" >&2
    exit 1
  fi
  exit 0
fi

tmp="$(mktemp -d "${TMPDIR:-/tmp}/os-wasm-check.XXXXXX")"
trap 'rm -rf "$tmp"' EXIT
generate_into "$tmp"
status=0
for pair in "graph_kit_os.js:$PKG_DIR/graph_kit_os.js" \
            "graph_kit_os.d.ts:$PKG_DIR/graph_kit_os.d.ts" \
            "bytes.ts:$BYTES_TS"; do
  built="$tmp/${pair%%:*}"
  committed="${pair#*:}"
  if ! diff -q "$built" "$committed" >/dev/null 2>&1; then
    echo "check failed: $committed differs from a fresh build" >&2
    status=1
  fi
done
if [ "$status" -ne 0 ]; then
  echo "run scripts/build-os-wasm.sh and commit the result" >&2
  exit 1
fi
echo "ok: generated OS wasm files match a fresh build"
